mapper.sql:
select e.id, e.platform, e.file_name, e.file_path, e.product_count, e.record_count, e.remark, e.create_by, e.create_time, e.update_by, e.update_time, f.filtered_record_count, f.filtered_product_count, f.filtered_time, f.filter_version
from product_execution_list e
left join product_execution_list_filter f on f.list_id = e.id and f.owner_id = #{params.ownerId}

mapper.select:


     and e.file_name like concat('%', #{fileName}, '%')
     and e.platform = #{platform}

order by e.id desc

mapper.update:
update product_execution_list
remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}
